mapper.select:
SELECT 
  FROM graph_review_item
 WHERE graph_review_item.status = #{status}
   AND graph_review_item.item_type = #{itemType}

   AND 
 ORDER BY graph_review_item.created_at, graph_review_item.id

mapper.update:
UPDATE graph_review_item
   SET status = #{status},
       decided_by = #{decidedBy},
       decided_at = #{decidedAt}
 WHERE id = #{id}
   AND status = 'pending'
